<template>
  <view class="dispute-page">
    <view v-if="loading" class="state">异议信息加载中...</view>
    <template v-else-if="record">
      <view class="hero"><text class="eyebrow">{{ statusText(record.status) }}</text><text class="title">{{ record.itemName }}</text><text class="line hero-line">{{ record.institutionName }}</text><text v-if="record.deadline" class="line hero-line">下一次反馈期限 {{ formatTime(record.deadline) }}</text></view>
      <view class="card"><text class="card-title">我的异议</text><text class="line">{{ record.description }}</text><text class="line">原服务完成时间：{{ record.completedAt ? formatTime(record.completedAt) : '—' }}</text><text class="line">执行人员：{{ record.performedByName || '机构登记' }}</text><text class="line">客服负责人：{{ record.ownerName || '等待平台受理' }}</text></view>
      <view v-if="record.evidence" class="card"><text class="card-title">机构业务反馈</text><text class="line">{{ record.evidence }}</text></view>
      <view v-if="record.proposal" class="card"><text class="card-title">{{ record.status === 'review_proposed' ? '平台复核方案' : '当前处理方案' }} · {{ outcomeText(record.outcome) }}</text><text class="line">{{ record.proposal }}</text><text v-if="record.correctedItemName" class="line">实际项目：{{ record.correctedItemName }}；原项目恢复 1 次，实际项目扣减 1 次。</text><text v-if="record.restoredExpiresAt" class="line">恢复后有效期至 {{ formatTime(record.restoredExpiresAt) }}</text><text v-if="record.outcome === 'refund'" class="line">例外退费 ¥{{ (record.refundAmountFen / 100).toFixed(2) }}。您接受后生成退款申请，仍需财务审核及微信确认。</text>
        <view v-if="['proposed','review_proposed'].includes(record.status)" class="actions"><button class="primary" :disabled="submitting" @tap="accept">接受处理方案</button><button class="secondary" :disabled="submitting" @tap="responseVisible = true">{{ record.status === 'proposed' ? '不同意，申请独立复核' : '不接受，继续协调' }}</button></view>
      </view>
      <view v-if="record.settlementHeld" class="notice">异议尚未解决，平台会继续协调。其他无争议服务可以继续使用；不会因您未回复而自动结案。</view>
<button v-if="record.status === 'awaiting_rebooking'" class="primary" @tap="rebook">选择重新服务的时间</button>
      <button v-if="record.replacementAppointmentId" class="secondary" @tap="goReplacement">查看已确认的新预约</button>
      <button v-if="record.refundId" class="secondary" @tap="goRefund">查看关联退款进度</button>
      <view class="card"><text class="card-title">处理记录</text><view v-for="entry in [...record.events].reverse()" :key="entry.id" class="event"><text class="event-title">{{ eventText(entry.eventType) }}</text><text class="line">{{ entry.detail }}</text><text class="event-time">{{ formatTime(entry.createdAt) }}</text></view></view>
      <button class="secondary" @tap="load">刷新进度</button>
      <ServiceSupport title="服务异议咨询" :path="`/pages/services/dispute-detail?id=${record.id}`" :session-from="`service_dispute_${record.id}`" :information="`异议编号：${record.id}\n当前状态：${statusText(record.status)}`" />
    </template>
    <template v-else-if="appointment">
      <view class="hero"><text class="eyebrow">反馈服务记录问题</text><text class="title">{{ appointment.entitlement.orderItem.itemName }}</text><text class="line hero-line">{{ appointment.institution.name }}</text></view>
      <view class="card"><text class="card-title">异议类型</text><picker :range="reasonOptions" range-key="label" :value="reasonIndex" @change="reasonIndex = Number($event.detail.value)"><view class="reason-row"><text>{{ reasonOptions[reasonIndex].label }}</text><text>›</text></view></picker><text class="card-title">业务问题说明</text><textarea v-model="description" maxlength="1000" class="description" placeholder="说明未接受服务、项目或次数不符等问题，请勿填写专业诊疗资料" /><text class="counter">{{ description.length }}/1000</text></view>
      <view class="notice">平台客服将受理并联系您，机构提供业务执行依据。您明确接受方案且完成处理后才结案；不同意时可申请独立复核。</view>
      <button class="primary" :disabled="submitting || !description.trim()" @tap="submit">{{ submitting ? '提交中...' : '提交服务异议' }}</button>
    </template>
    <view v-else class="state"><text>信息加载失败，请重试</text><button class="secondary" @tap="load">重新加载</button></view>
    <view v-if="responseVisible" class="mask" @tap="responseVisible = false"><view class="sheet" @tap.stop><view class="sheet-head"><text>{{ record?.status === 'proposed' ? '申请独立复核' : '继续争议协调' }}</text><text @tap="responseVisible = false">关闭</text></view><textarea v-model="responseNote" maxlength="1000" class="description" placeholder="说明不接受结果的原因和希望进一步核对的事项" /><button class="primary" :disabled="submitting || !responseNote.trim()" @tap="respond">确认提交</button></view></view>
  </view>
</template>
<script setup lang="ts">
import { ref } from 'vue'
import { onLoad, onShow } from '@dcloudio/uni-app'
import ServiceSupport from '@/components/business/ServiceSupport.vue'
import { serviceProgramApi, type ServiceAppointment, type ServiceDispute } from '@/api/modules/service-program'
const id = ref(0), appointmentId = ref(0), appointment = ref<ServiceAppointment | null>(null), record = ref<ServiceDispute | null>(null), loading = ref(true), submitting = ref(false), description = ref(''), reasonIndex = ref(0), responseVisible = ref(false), responseNote = ref('')
const requestId = `dispute-${Date.now()}-${Math.random().toString(36).slice(2)}`
const reasonOptions = [{ value: 'not_received', label: '未接受该服务' }, { value: 'wrong_item', label: '服务项目不符' }, { value: 'wrong_quantity', label: '扣减次数不符' }, { value: 'other', label: '其他服务问题' }]
async function load() { loading.value = true; try { if (id.value) record.value = await serviceProgramApi.dispute(id.value); else if (appointmentId.value) { appointment.value = await serviceProgramApi.appointment(appointmentId.value); const existing = await serviceProgramApi.appointmentDispute(appointmentId.value); if (existing) { record.value = existing; id.value = existing.id } } } catch { record.value = null; appointment.value = null } finally { loading.value = false } }
async function submit() { if (!appointmentId.value || !description.value.trim() || submitting.value) return; submitting.value = true; try { const result = await serviceProgramApi.createDispute(appointmentId.value, { reasonType: reasonOptions[reasonIndex.value].value, description: description.value.trim(), clientRequestId: requestId }); uni.redirectTo({ url: `/pages/services/dispute-detail?id=${result.id}` }) } catch { /* 请求层展示业务错误 */ } finally { submitting.value = false } }
async function accept() { if (!record.value || submitting.value) return; const result = await uni.showModal({ title: '接受处理方案', content: record.value.outcome === 'refund' ? `接受例外退费 ¥${(record.value.refundAmountFen / 100).toFixed(2)} 的方案，之后进入退款审核；此时不代表钱已到账。` : record.value.outcome === 'rearrange' ? '接受后恢复 1 次权益，请重新选择时间；平台关联已确认的新预约后再结案。' : `接受“${outcomeText(record.value.outcome)}”方案，执行相应处理后结案。`, confirmText: '确认接受' }); if (!result.confirm) return; submitting.value = true; try { record.value = await serviceProgramApi.disputeAction(record.value.id, { action: 'accept', expectedUpdatedAt: record.value.updatedAt }); uni.showToast({ title: '方案已确认', icon: 'success' }) } catch { /* 请求层展示业务错误 */ } finally { submitting.value = false } }
async function respond() { if (!record.value || !responseNote.value.trim() || submitting.value) return; submitting.value = true; try { record.value = await serviceProgramApi.disputeAction(record.value.id, { action: record.value.status === 'proposed' ? 'review' : 'disagree', expectedUpdatedAt: record.value.updatedAt, note: responseNote.value.trim() }); responseVisible.value = false; responseNote.value = ''; uni.showToast({ title: '反馈已提交', icon: 'success' }) } catch { /* 请求层展示业务错误 */ } finally { submitting.value = false } }
function rebook() { if (record.value) uni.navigateTo({ url: `/pages/services/appointment?planId=${record.value.planId}&entitlementId=${record.value.entitlementId}` }) }
function goReplacement() { if (record.value?.replacementAppointmentId) uni.navigateTo({ url: `/pages/services/appointment-detail?id=${record.value.replacementAppointmentId}` }) }
function goRefund() { if (record.value?.refundId) uni.navigateTo({ url: `/pages/services/refund-detail?id=${record.value.refundId}` }) }
function formatTime(value: string) { return new Date(value).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false }) }
function statusText(value: string) { return ({ submitted: '等待客服受理', evidence_pending: '等待机构依据', processing: '平台处理中', proposed: '请确认处理方案', review_requested: '独立复核中', review_proposed: '请确认复核方案', disputed: '争议继续协调', awaiting_rebooking: '权益已恢复，等待新预约确认', executing: '退费执行中', resolved: '处理已完成' } as Record<string,string>)[value] || value }
function outcomeText(value: string) { return ({ maintain: '维持记录', correct_item: '纠正实际项目，调整次数', restore: '纠正扣次，恢复权益', rearrange: '恢复权益，重新预约', refund: '例外退费' } as Record<string,string>)[value] || value }
function eventText(value: string) { return ({ submitted: '异议已提交', contact: '客服已联系', evidence: '机构已提供依据', propose: '处理方案已反馈', review: '独立复核方案已反馈', review_requested: '已申请复核', disputed: '不同意结果，继续协调', accepted: '我已接受方案', refund_success: '退费已完成并结案', extend: '反馈期限已调整', retry_refund: '退费申请已更新', compensation_created: '例外退费申请已生成', finish_rearrange: '新的预约已确认，重新安排完成' } as Record<string,string>)[value] || '进度更新' }
onLoad(options => { id.value = Number(options?.id) || 0; appointmentId.value = Number(options?.appointmentId) || 0 })
onShow(() => { void load() })
</script>
<style scoped>
.dispute-page { min-height:100vh; padding:24rpx 24rpx calc(40rpx + env(safe-area-inset-bottom)); background:var(--color-bg); }.state { display:flex; min-height:50vh; flex-direction:column; align-items:center; justify-content:center; gap:24rpx; color:var(--color-text-secondary); }.hero { padding:32rpx; border-radius:24rpx; color:#fff; background:linear-gradient(135deg,#173b34,#087c51); }.eyebrow { display:block; color:#9de8bd; font-size:23rpx; }.title { display:block; margin-top:14rpx; font-size:36rpx; font-weight:750; }.card { padding:28rpx; margin-top:20rpx; border-radius:20rpx; background:#fff; }.card-title { display:block; font-size:28rpx; font-weight:700; margin-bottom:14rpx; }.line { display:block; margin-top:12rpx; color:var(--color-text-secondary); font-size:24rpx; line-height:1.7; white-space:pre-wrap; overflow-wrap:anywhere; }.hero-line { color:rgba(255,255,255,.8); }.description { box-sizing:border-box; width:100%; min-height:220rpx; padding:22rpx; border:1rpx solid var(--color-border); border-radius:12rpx; font-size:25rpx; line-height:1.6; }.counter { display:block; text-align:right; color:var(--color-text-tertiary); font-size:21rpx; margin-top:8rpx; }.reason-row { display:flex; justify-content:space-between; padding:20rpx 0; margin-bottom:20rpx; font-size:25rpx; border-bottom:1rpx solid var(--color-border); }.primary,.secondary { margin-top:22rpx; padding:0 24rpx; border-radius:14rpx; font-size:26rpx; font-weight:650; }.primary { color:#fff; background:var(--color-primary); }.secondary { border:1rpx solid var(--color-border); color:var(--color-primary); background:#fff; }.primary[disabled] { opacity:.5; }.notice { padding:22rpx 8rpx; color:var(--color-text-secondary); font-size:23rpx; line-height:1.7; }.event { padding:22rpx 0; border-bottom:1rpx solid var(--color-border); }.event:last-child { border:0; }.event-title { font-weight:650; font-size:25rpx; }.event-time { display:block; color:var(--color-text-tertiary); font-size:21rpx; margin-top:8rpx; }.mask { position:fixed; inset:0; z-index:100; background:rgba(0,0,0,.4); display:flex; align-items:flex-end; }.sheet { box-sizing:border-box; width:100%; padding:28rpx 24rpx calc(28rpx + env(safe-area-inset-bottom)); border-radius:24rpx 24rpx 0 0; background:#fff; }.sheet-head { display:flex; justify-content:space-between; margin-bottom:24rpx; font-size:28rpx; font-weight:700; }
</style>
